  /* >>> fuku omikuji */
  // Fukukitaru mod. Omikuji setting (Mods > Edit): Expanded or Classic (the original 5 slips).
  // Gameplay rolls use the game's seeded rnd() so online rollback stays in sync.
  var FUKU_EXP = p.cid === 'fuku' && FUKU_MODE_EXP;
  // Expanded: Dice Shot -- Fortune Shot's damage is rolled on a die (avg = normal damage)
  if (ev === 'proj' && FUKU_EXP && !p.__fukuDice && p.move && p.move.proj && p.move.id && baseId(p.move.id) === '5S') {
    var die = 1 + Math.floor(rnd() * 6), pj = p.move.proj, orig = pj.hit;
    pj.hit = Object.assign({}, orig, { dmg: Math.round(orig.dmg * die / 3.5) });
    p.__fukuDice = true;
    try { doEvent(p, ev); } finally { pj.hit = orig; p.__fukuDice = false; }
    addText('DICE ' + die, p.x + p.facing * 70, GY - 190, die >= 5 ? '#ffd24a' : die <= 2 ? '#9fa8c0' : '#ffffff', die >= 5 ? 26 : 20, 40);
    return;
  }
  // Expanded: Prayer -- each taunt adds 10% luck (max 50%) = chance a curse is re-drawn on her next Omikuji.
  // No return: the game's own taunt handling (Spurt gain, taunt line) still runs below.
  if (ev === 'taunt' && FUKU_EXP) {
    p.fukuLuck = Math.min(0.5, (p.fukuLuck || 0) + 0.1);
    addText('LUCK ' + Math.round(p.fukuLuck * 100) + '%', p.x, GY - 250, '#ffe39a', 18, 45);
  }
  if (ev === 'omikujiDraw' || ev === 'omikujiFire') {
    var BAD = function (s) { return s === 'kyo' || s === 'daikyo'; };
    var LAB = { daikichi: ['大吉 GREAT BLESSING', '#ffd24a'], kichi: ['吉 BLESSING', '#8affa0'], shokichi: ['小吉 SMALL BLESSING', '#9fd0ff'],
      fate: ['運命 FATE SWAP', '#c9a0ff'], double: ['二枚 DOUBLE DRAW', '#ffffff'], kyo: ['凶 CURSE', '#ff8a8a'], daikyo: ['大凶 GREAT CURSE', '#ff4a4a'] };
    if (ev === 'omikujiDraw') {
      // Classic: 15 / 25 / 20 / 25 / 15.   Expanded: 12 / 18 / 15 / fate 10 / double 10 / 22 / 13.
      var roll = FUKU_EXP
        ? function () { var r = rnd(); return r < 0.12 ? 'daikichi' : r < 0.30 ? 'kichi' : r < 0.45 ? 'shokichi' : r < 0.55 ? 'fate' : r < 0.65 ? 'double' : r < 0.87 ? 'kyo' : 'daikyo'; }
        : function () { var r = rnd(); return r < 0.15 ? 'daikichi' : r < 0.40 ? 'kichi' : r < 0.60 ? 'shokichi' : r < 0.85 ? 'kyo' : 'daikyo'; };
      var slip = roll(), redraw = false;
      if (BAD(slip) && p.move && p.move.exRedraw) redraw = true;                               // EX: always re-draw a curse
      else if (BAD(slip) && FUKU_EXP && rnd() < (p.fukuLuck || 0)) redraw = true;      // Prayer luck
      if (redraw) { slip = roll(); addText('RE-DRAW!', p.x, GY - 272, '#ffffff', 18, 50); }
      if (FUKU_EXP) p.fukuLuck = 0;
      var slips = [slip];
      if (slip === 'double') {                       // two more slips (never another Double Draw), both applied
        var sub = function () { var s; do { s = roll(); } while (s === 'double'); return s; };
        slips = [sub(), sub()];
      }
      var forced = fukuForcedSlip(p);   // Omikuji combo trials pick the slip (never outside a trial)
      if (forced) { slip = forced[0]; slips = forced.length > 1 ? forced.slice(1) : [slip]; addText('FORCED FOR THIS TRIAL', p.x, GY - 288, '#ffd24a', 15, 75); }
      p.fukuSlips = slips; p.fukuSlip = slips[0];
      var head = LAB[slip];
      addText(head[0], p.x, GY - 235, head[1], 26, 75); p.flash = 8;
      if (slip === 'double') addText(LAB[slips[0]][0].split(' ')[0] + ' + ' + LAB[slips[1]][0].split(' ')[0], p.x, GY - 205, '#ffffff', 22, 75);
      try { Sfx.play(slips.some(BAD) ? 'hit' : 'power'); } catch (e) {}
    } else {
      var o = opp(p);
      var resetCombo = function (d) { d.combo = 0; d.comboDmg = 0; d.jug = 0; d.comboT = 0; d.gbUsed = d.wbUsed = false; d.bounce = null; d.limitHit = false; d.ipsLog = ''; };
      var bolt = function (x) {
        spawnFx({ x: x, y: GY, facing: 1, side: p.side, c: p.c }, { type: 'pillar', w: 74, h: 760, color: '#fff27a', dur: 24 });
        if (!G.resim) for (var i = 0; i < 7; i++) G.fx.push({ type: 'spark', x: x + (Math.random() - .5) * 50, y: GY - Math.random() * 220, kind: 'hit', lvl: 3, dir: 0, t: 0, life: 16 + i, rot: Math.random() * 6 });
        G.shake = Math.max(G.shake || 0, 12); G.freeze = Math.max(G.freeze || 0, 10);
      };
      var apply = function (slip) {
        if (slip === 'daikichi') {            // divine lightning strikes the opponent: unblockable, launches
          p.meter = 100; p.flash = 14;
          if (typeof callout === 'function') callout(p, '大吉 DIVINE LIGHTNING', 'spurt');
          bolt(o.x);
          if (o.c.ec && typeof ecStrongHit === 'function') {
            if (hurtboxOK(o) && !invulnerable(o, false) && !o.ecLaunch) ecStrongHit(p, o, p.x); else addText('MISS', o.x, GY - 200, '#cfe3ff', 22, 40);
          } else if (hurtboxOK(o) && !invulnerable(o, false)) {
            var dmg = 1800;
            resetCombo(o); dealDamage(p, o, dmg, 0); clearProjs(o); o.combo = 1; o.prorate = 1; noteDamage(o, dmg);
            o.setState('airHit'); o.kd = true; o.hardKd = false; o.vx = (o.x >= p.x ? 1 : -1) * 2.5; o.vy = -13; o.y = Math.min(o.y, GY - 1);
            o.hitLvl = 3; contact(p, o);
          } else addText('MISS', o.x, GY - 200, '#cfe3ff', 22, 40);
          try { Sfx.play('heavy'); } catch (e) {}
        } else if (slip === 'kichi') {        // 6 s speed + damage buff, +25 Spurt
          p.guts = 360; p.gold = 360; p.meter = Math.min(100, p.meter + 25); p.flash = 12;
          if (typeof callout === 'function') callout(p, '吉 BLESSING', 'spurt');
          try { Sfx.play('power'); } catch (e) {}
        } else if (slip === 'shokichi') {     // heal
          var heal = Math.max(0, Math.min(1000, p.c.hp - p.hp)); p.hp += heal; p.flash = 10;
          addText('+' + heal + ' HP', p.x, GY - 200, '#8affa0', 22, 50);
          spawnFx(p, { type: 'motif', y: -110, n: 10, spread: 60 });
          try { Sfx.play('power'); } catch (e) {}
        } else if (slip === 'fate') {         // swap HP percentages with the opponent
          var mine = p.hp / p.c.hp, theirs = o.hp / o.c.hp;
          var snap = function (d, pct) { return d.c.ec ? Math.max(1, Math.round(Math.max(1, Math.round(pct * 12)) * d.c.hp / 12)) : Math.max(1, Math.round(pct * d.c.hp)); };
          p.hp = snap(p, theirs); o.hp = snap(o, mine);
          p.flash = 12; o.flash = 12; G.shake = Math.max(G.shake || 0, 8);
          addText('FATE SWAP ' + Math.round(mine * 100) + '% <-> ' + Math.round(theirs * 100) + '%', (p.x + o.x) / 2, GY - 230, '#c9a0ff', 22, 70);
          spawnFx(p, { type: 'ring', y: -90, r: 80, color: '#c9a0ff' }); spawnFx(o, { type: 'ring', y: -90, r: 80, color: '#c9a0ff' });
          try { Sfx.play('power'); } catch (e) {}
        } else if (slip === 'kyo') {          // dizzy: stuck standing and hittable for 50 f, -25 Spurt
          resetCombo(p); p.setState('hit'); p.hs = 50; p.crouchHit = false; p.vx = 0; p.hitLvl = 1;
          p.meter = Math.max(0, p.meter - 25);
          addText('DIZZY!', p.x, GY - 200, '#ff8a8a', 22, 50);
          spawnFx(p, { type: 'motif', y: -175, n: 6, spread: 30 });
          try { Sfx.play('hit'); } catch (e) {}
        } else if (slip === 'daikyo') {       // lightning strikes her, launched and juggleable
          bolt(p.x);
          resetCombo(p); p.hp = Math.max(1, p.hp - 1500); p.meter = 0; p.flash = 16;
          p.setState('airHit'); p.kd = true; p.hardKd = true; p.vy = -11; p.vx = -p.facing * 2; p.y = Math.min(p.y, GY - 1); p.hitLvl = 3;
          try { Sfx.play('heavy'); } catch (e) {}
        }
      };
      var list = p.fukuSlips || [p.fukuSlip || 'shokichi'];
      for (var k = 0; k < list.length; k++) apply(list[k]);
    }
    return;
  }
  /* <<< fuku omikuji */
